import unittest

def multiply(a, b):
    return abs(a % 10) * abs(b % 10)

class TestMultiply(unittest.TestCase):
    def test_positive_numbers(self):
        self.assertEqual(multiply(12, 3), 6)
        self.assertEqual(multiply(25, 14), 20)

    def test_negative_numbers(self):
        self.assertEqual(multiply(-12, 3), 6)
        self.assertEqual(multiply(-12, -3), 6)
        self.assertEqual(multiply(12, -3), 6)

    def test_single_digits(self):
        self.assertEqual(multiply(5, 7), 35)
        self.assertEqual(multiply(0, 9), 0)

    def test_zero(self):
        self.assertEqual(multiply(0, 0), 0)
        self.assertEqual(multiply(10, 20), 0)

    def test_large_numbers(self):
        self.assertEqual(multiply(123456, 789012), 12)

if __name__ == "__main__":
